93	// 错误，结果为空（无发行条目、无失败藏品编号、不标回放、业务错误为空），
94	// 请求号不被这次未保存的拒绝占用，任何藏品都不新增登记、持有或发行历史，
95	// 历史序号不被消耗，未首次发行的系列也不因此固定版税规则；保存条件恢复
96	// 后用完全相同的请求重提，按当时的业务状态重新判断：拒绝条件仍在则重新
97	// 保存此次拒绝并返回对应业务错误（这次不算回放），状态已变为满足请求则
98	// 整批正常发行。
99	func (r *Registry) IssueBatch(req IssueBatchRequest) (IssueBatchResult, error) {
100		if err := req.validatePresent(); err != nil {
101			return IssueBatchResult{}, err
102		}
103		r.mu.Lock()
104		defer r.mu.Unlock()
105		if err := r.checkOpen(); err != nil {
106			return IssueBatchResult{}, err
107		}
108	
109		key := requestKey(req.Operator, req.RequestID)
110		sig := issueBatchParamsSig(req)
111		if prev, ok := r.state.Requests[key]; ok {
112			return r.replayIssueBatch(prev, sig)
113		}
114	
115		itemID, bizErr := r.checkIssueBatch(req)
116		if bizErr != nil {
117			if !isValidationErr(bizErr) {
118				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号
119				// 并落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
120				r.state.Requests[key] = request{
121					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue_batch",
122					Params: sig, Rejected: true, Reason: errCode(bizErr),
123					ItemID: itemID,
124				}
125				if err := r.commit(); err != nil {
126					// 拒绝结果落盘失败：这次拒绝没有被记住，不能只用业务错误
127					// 掩盖保存错误——调用者稍后用原请求重提时必须按当时状态
128					// 重新判断，而不是回放一个实际没有保存的拒绝。commit 失败
129					// 时已按磁盘内容重建状态，请求记录随之撤销；此处再删一次
130					// 以覆盖磁盘暂时不可读、状态未能重建的情形。整体返回：没有
131					// 发行条目、没有失败藏品编号、不标回放、结果中业务错误为空，
132					// error 保留实际写入错误。
133					delete(r.state.Requests, key)
134					return IssueBatchResult{}, err
135				}
136			}
137			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
138			return IssueBatchResult{ItemID: itemID, Err: bizErr}, bizErr
139		}
140	
141		// 在同一临界区内依次为每件建立登记、持有与发行历史，序号连续递增；
142		// 与其他操作互斥，整批记录之间不会插入其他发行或转让。
143		items := make([]IssueBatchItem, 0, len(req.Entries))
144		stored := make([]batchItemResult, 0, len(req.Entries))
145		for _, e := range req.Entries {
146			seq := r.state.NextSeq + 1
147			r.state.NextSeq = seq
148			r.state.Items[e.ItemID] = item{
149				ID: e.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
150				Metadata: e.Metadata, IssuedTxID: seq,
151			}
152			r.state.Holdings[e.ItemID] = holding{ItemID: e.ItemID, OwnerID: e.HolderID, Version: 1}
153			r.state.History = append(r.state.History, historyEntry{
154				Seq: seq, Kind: "issue", ItemID: e.ItemID, Operator: req.Operator,
155				Reason: req.Reason, RequestID: req.RequestID,
156				FromID: "", ToID: e.HolderID, FromVersion: 0, ToVersion: 1,
157			})
158			items = append(items, IssueBatchItem{ItemID: e.ItemID, OwnerID: e.HolderID, Version: 1, TxSeq: seq})
159			stored = append(stored, batchItemResult{ItemID: e.ItemID, OwnerID: e.HolderID, TxSeq: seq})
160		}
161		r.state.Requests[key] = request{
162			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue_batch",
163			Params: sig, Batch: stored,
164		}
165		if err := r.commit(); err != nil {
166			return IssueBatchResult{}, err
167		}
168		return IssueBatchResult{Items: items}, nil
169	}
