174	// 清单顺序最前的那件。任何一件不通过则整批拒绝。
175	func (r *Registry) checkIssueBatch(req IssueBatchRequest) (string, error) {
176		return r.checkBatchIssueEligibility(req.Operator, req.SeriesID, req.Entries)
177	}
