191		for _, bi := range prev.Batch {
192			res.Items = append(res.Items, IssueBatchItem{
193				ItemID: bi.ItemID, OwnerID: bi.OwnerID, Version: 1, TxSeq: bi.TxSeq,
194			})
195		}
196		return res, nil
